package com.aoo.bcg.common.error;import java.util.Objects;import java.util.concurrent.atomic.AtomicBoolean;
/** Stable business failure preserving code, trace and root cause while preventing duplicate stack logging. */
public final class DomainFailure extends RuntimeException{private final int code;private final String traceId;private final AtomicBoolean logged=new AtomicBoolean();public DomainFailure(int code,String userMessage,String traceId,Throwable cause){super(Objects.requireNonNull(userMessage),cause);if(code<1000||code>6999||traceId==null||traceId.isBlank())throw new IllegalArgumentException("invalid domain failure");this.code=code;this.traceId=traceId;}public int code(){return code;}public String traceId(){return traceId;}public boolean claimStackLog(){return logged.compareAndSet(false,true);}public PublicError publicError(){return new PublicError(code,getMessage(),traceId);}public record PublicError(int code,String message,String traceId){}}
